-- Run in the Supabase SQL editor before enabling production use.
create extension if not exists "pgcrypto";
create type public.order_status as enum ('pending_contact','confirmed','processing','shipped','delivered','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, is_admin boolean not null default false, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, gender text, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), sku text not null unique, name text not null, slug text not null unique, description text, category_id uuid references public.categories(id), price_kes integer not null check(price_kes >= 0), sale_price_kes integer check(sale_price_kes >= 0), featured boolean not null default false, is_new boolean not null default false, active boolean not null default true, seo_title text, seo_description text, created_at timestamptz not null default now());
create table public.product_images (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, storage_path text not null, alt_text text, sort_order int not null default 0);
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, sku text not null unique, size text, color text, stock_quantity int not null default 0 check(stock_quantity >= 0));
create table public.addresses (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, full_name text not null, phone text not null, county text, location text not null, instructions text, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), customer_name text not null, customer_phone text not null, address_id uuid references public.addresses(id), status public.order_status not null default 'pending_contact', subtotal_kes integer not null check(subtotal_kes >= 0), delivery_fee_kes integer not null default 0, total_kes integer not null check(total_kes >= 0), notes text, created_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, variant_id uuid references public.product_variants(id), product_name text not null, unit_price_kes integer not null, quantity int not null check(quantity > 0), size text, color text);
create table public.wishlists (user_id uuid not null references auth.users(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,product_id));
create table public.reviews (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, user_id uuid references auth.users(id), rating int not null check(rating between 1 and 5), body text, approved boolean not null default false, created_at timestamptz not null default now());
create table public.newsletter_subscribers (id uuid primary key default gen_random_uuid(), email text not null unique, consented_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.wishlists enable row level security; alter table public.reviews enable row level security; alter table public.newsletter_subscribers enable row level security;
create policy "profiles own" on public.profiles for select using (auth.uid()=id); create policy "addresses own" on public.addresses for all using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy "orders own" on public.orders for select using (auth.uid()=user_id); create policy "wishlists own" on public.wishlists for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
-- Add admin-only policies after creating a stable is_admin() SECURITY DEFINER function. Never expose service role keys to the browser.
